   p=struct.unpack_from('<I',b,off+4*i)[0]
   while b[p]&128:p+=1
   p+=1;q=b.index(b'\0',p);items.append(('string_id:'+str(i),b[p:q]))
 else:items=[('byte_offset:'+str(m.start()),m.group()) for m in re.finditer(rb'[\x20-\x7e]{16,2000}',b)]
 count=0
 for loc,s in items:
  shape=None
